// Transform OLTP records: Seasonality tagging, Line Ratio Debt Allocation & Gross Profit
const items = $input.all();
return items.map(item => {
  const row = item.json;
  const orderDate = new Date(row.order_date || Date.now());
  const month = orderDate.getMonth() + 1;
  const seasonType = [1, 2, 12].includes(month) ? 'TET_SEASON' : 'NORMAL';
  const standardCogs = Number(row.quantity || 0) * Number(row.estimated_cost || 0);
  const revenue = Number(row.line_total || 0);
  const grossProfit = revenue - standardCogs;
  const totalAmount = Number(row.total_amount || 0);
  const orderDebt = totalAmount - Number(row.paid_amount || 0);
  const lineRatio = totalAmount > 0 ? revenue / totalAmount : 0;
  const outstandingAmount = Math.round(orderDebt * lineRatio * 100) / 100;
  return {
    json: {
      ...row,
      season_type: seasonType,
      standard_cogs: standardCogs,
      gross_profit: grossProfit,
      outstanding_amount: outstandingAmount,
      synced_at: new Date().toISOString()
    }
  };
});
